import { MeshBasicNodeMaterial, PlaneGeometry, Group, Mesh } from 'three/webgpu';

/**
 * Creates a sprite-like textured plane with atlas UV cropping.
 * No interactivity, no animation, static composition.
 */
export default function createNode(config, ctx) {
  const group = new Group();
  group.userData.handlers = {};

  // Atlas source rect dimensions (pixels)
  const srcW = 512;
  const srcH = 320;
  const aspect = srcW / srcH;

  // Plane geometry sized to aspect ratio (width ~1.8 units, height auto)
  const planeWidth = 1.8;
  const planeHeight = planeWidth / aspect;

  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: 2,              // DoubleSide – sprite-like visibility
    depthWrite: false,
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load texture – atlas contains the region we need
  const texPromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texPromise.then((tex) => {
    // Calculate UV repeat & offset for the source rect
    // Assumes texture origin at bottom‑left; source rect top‑left in pixel coords
    const fullW = tex.image.width;
    const fullH = tex.image.height;

    const repeatU = srcW / fullW;
    const repeatV = srcH / fullH;
    const offsetU = 0;
    const offsetV = 1 - repeatV;   // top‑left rect → bottom‑left UV

    tex.repeat.set(repeatU, repeatV);
    tex.offset.set(offsetU, offsetV);
    tex.needsUpdate = true;

    material.map = tex;
    material.needsUpdate = true;
  }).catch(() => {});

  // Cleanup – dispose material and geometry (texture remains cached)
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return group;
}
